// Read every field from the form (column names are dynamic)
const j = $json;
const skip = ['Timestamp', 'Time', 'Number'];

let content = '';
for (const [k, v] of Object.entries(j)) {
  if (skip.some(s => k.toLowerCase().includes(s.toLowerCase()))) continue;
  content += '*' + k + ':* ' + (v || '-') + '\n';
}

const name = j['Name'] || j['Full Name'] || j['Nama'] || 'Customer';

return [{
  json: {
    notification: '📩 *NEW ORDER FROM FORM*\n\nFrom: ' + name + '\n\n' + content + '\nFollow up right away!',
    name: name,
    full_content: content
  }
}];

